  const d=open('Export '+moduleTitle,historyBar()+'<p class="rf-note">Choose records and columns independently. Your export runs in the background and stays available for 24 hours.</p><div class="rf-column-grid"><label class="rf-field">Records to export<select id="rf-export-scope"><option value="page">Current page ('+state.records.length+')</option><option value="selected" '+(!state.selected.size||allMatching?'disabled':'')+'>Selected records ('+state.selected.size+')</option><option value="matching">All matching results ('+state.total+')</option><option value="all">All authorized records</option><option value="custom">Custom export filters</option></select></label><label class="rf-field">File format<select id="rf-export-format"><option value="xlsx">Excel (.xlsx)</option><option value="csv">CSV (UTF-8)</option></select></label><label class="rf-field">Columns<select id="rf-export-columns"><option value="current">Current displayed columns</option><option value="default">Default View columns</option><option value="my">My View columns</option><option value="all">All permitted columns</option><option value="custom">Custom selection</option></select></label><div class="rf-field rf-timezone-info"><span>Export time zone</span><span id="rf-export-timezone">'+esc(exportTimeZone())+'</span><small>Date/time columns include separate time-zone columns.</small></div></div><label class="rf-check rf-warning" id="rf-export-all-confirm" hidden><input type="checkbox" id="rf-confirm-all"> Export all records I am authorized to access, without the current filters.</label><div id="rf-export-custom-filter" hidden></div><div id="rf-export-custom-columns" hidden><div class="rf-actions">'+btn('Select all permitted','export-all-columns')+btn('Clear selection','export-clear-columns')+btn('Expand all','export-expand')+btn('Collapse all','export-collapse')+'</div>'+[...new Set([...groups,...fields.map(f=>f.group||'Other Information')])].map(group=>{const entries=fields.filter(f=>(f.group||'Other Information')===group);return entries.length?'<details class="rf-group rf-export-group" open><summary><label><input type="checkbox" data-export-group="'+esc(group)+'"> '+esc(group)+'</label><span class="rf-group-count"></span></summary><div class="rf-column-grid">'+entries.map(f=>'<label class="rf-check"><input type="checkbox" data-export-column="'+f.key+'" '+(prefs.columns.includes(f.key)?'checked':'')+'> '+esc(f.label)+'</label>').join('')+'</div></details>':'';}).join('')+'<p class="rf-note" id="rf-export-column-count"></p></div><div id="rf-export-plan"></div><p class="rf-note" id="rf-export-format-note">Excel includes a formatted data table, frozen headers and an Export Details sheet. Only the exported table is styled.</p><p class="rf-note">Up to 500,000 authorized records, split into 1,000-row files. Downloads remain in Import/Export History when you leave this page.</p>',btn('Cancel','cancel')+btn('Review Export','plan',true));
  if(!d)return;d.classList.add('rf-transfer-dialog');bindHistory(d);const scope=d.querySelector('#rf-export-scope');scope.value=initial==='selected'?(allMatching?'matching':'selected'):initial;
  d.querySelector('[data-rf="cancel"]').onclick=()=>closeDialog();
  const invalidate=()=>{planned=null;requestId=uuid();d.querySelector('#rf-export-plan').innerHTML='';};
  const syncGroups=()=>{d.querySelectorAll('[data-export-group]').forEach(box=>{const checks=[...box.closest('.rf-export-group').querySelectorAll('[data-export-column]')],n=checks.filter(c=>c.checked).length;box.checked=n===checks.length;box.indeterminate=n>0&&n<checks.length;box.closest('summary').querySelector('.rf-group-count').textContent=n+'/'+checks.length;});d.querySelector('#rf-export-column-count').textContent=d.querySelectorAll('[data-export-column]:checked').length+' of '+fields.length+' available columns selected.';};syncGroups();
  d.querySelectorAll('[data-export-group]').forEach(box=>{box.onclick=e=>e.stopPropagation();box.onchange=()=>{box.closest('.rf-export-group').querySelectorAll('[data-export-column]').forEach(c=>c.checked=box.checked);syncGroups();invalidate();};});d.querySelectorAll('[data-export-column]').forEach(box=>box.onchange=syncGroups);
  for(const [action,value]of [['export-all-columns',true],['export-clear-columns',false]])d.querySelector('[data-rf="'+action+'"]').onclick=()=>{d.querySelectorAll('[data-export-column]').forEach(c=>c.checked=value);syncGroups();invalidate();};
  for(const action of ['expand','collapse'])d.querySelector('[data-rf="export-'+action+'"]').onclick=()=>d.querySelectorAll('.rf-export-group').forEach(g=>g.open=action==='expand');
  scope.onchange=()=>{d.querySelector('#rf-export-all-confirm').hidden=scope.value!=='all';const custom=d.querySelector('#rf-export-custom-filter');custom.hidden=scope.value!=='custom';if(scope.value==='custom'&&!customGetter)customGetter=filterBuilder(custom,query().filters);invalidate();};
